package main

import (
	"context"
	"fmt"
	"log"
	"strings"

	"github.com/jackc/pgx/v5"
)

func main() {
	rawData := `INSERT INTO houses_data (house_name, zodiac_sign, core_meaning, in_real_life, strengths, challenges, relationships, path_of_growth) VALUES
('House 4', 'Aries', 'The foundation of the self and the concept of home are tied to independence, action, and sometimes conflict. Childhood may have been energetic or competitive.', 'You view your home as a place of activity rather than just rest. You likely took on independence early in life and may have experienced a dynamic or assertive family environment.', 'Fierce protection of family, the ability to act decisively in domestic crises, and fostering independence in those you live with.', 'Arguments or impatience at home, a lack of peace in the domestic sphere, and difficulty settling down in one place.', 'You need a partner who respects your need to be the "head of the household" or at least your need for personal autonomy at home.', 'Learn to cultivate peace and stillness in your private life. Your home should also be a sanctuary, not just a battlefield.'),
('House 4', 'Taurus', 'The foundation of the self is built on material security, comfort, and sensory stability. A peaceful, beautiful home is essential for emotional well-being.', 'You invest heavily in your living space, preferring high-quality, comfortable furnishings. Your family life is likely stable, traditional, and centered around good food and comfort.', 'Creating a profoundly safe and beautiful home environment, loyalty to family traditions, and providing reliable emotional and material support.', 'Stubbornness regarding domestic changes, hoarding possessions, and staying in unhealthy living situations purely out of a desire for stability.', 'You express love to your family through material provision and physical affection. You need a partner who values domestic tranquility.', 'Embrace the fact that true security is internal. Learn to accept necessary changes in your domestic life without panic.'),
('House 4', 'Gemini', 'The concept of home and emotional foundation is tied to communication, variety, and intellectual stimulation. Childhood may have involved frequent moves or a busy household.', 'Your home is likely filled with books, gadgets, and constant conversation. You may view your living situation flexibly and could have multiple places you call "home."', 'An intellectually stimulating domestic life, adaptability to changing living situations, and a youthful, communicative approach to family.', 'Restlessness at home, a lack of deep emotional grounding, and a tendency to intellectualize feelings rather than experiencing them.', 'You need a partner who can keep up with a fast-paced, communicative household. Silence at home makes you uncomfortable.', 'Learn to ground yourself emotionally. Create spaces in your home dedicated to quiet reflection, away from constant mental stimulation.'),
('House 4', 'Cancer', 'The home is the absolute center of emotional life. The foundation is deeply tied to the mother, ancestry, and the nurturing of the soul.', 'You are deeply attached to your roots and your family. Your home is a private sanctuary where you retreat to heal and protect yourself from the outside world.', 'Profound emotional intelligence regarding family, the ability to create a truly nurturing environment, and a strong connection to heritage.', 'Clinging to the past, excessive nostalgia, suffocating family members with over-protectiveness, and retreating into your shell when threatened.', 'You seek a partner who feels like "home." Emotional security is the prerequisite for any deep domestic partnership.', 'Learn to differentiate between healthy nurturing and emotional codependency. Allow your loved ones the space to grow independently.'),
('House 4', 'Leo', 'The foundation of the self is tied to pride, creativity, and a sense of royalty. The home is a castle where you are the center of attention.', 'You take great pride in your home and family, often hosting gatherings to show them off. Childhood may have centered around a dominant or highly expressive parent.', 'Immense generosity toward family, a warm and welcoming domestic environment, and the ability to instill confidence in your loved ones.', 'Dictatorial behavior at home, demanding constant attention from family members, and prioritizing the appearance of the home over its emotional warmth.', 'You are the protective leader of your family. You need a partner who admires your domestic efforts and allows you to shine at home.', 'Learn that true leadership at home involves serving and listening, not just commanding. Share the domestic spotlight.'),
('House 4', 'Virgo', 'The foundation of the self is built on order, duty, and practical service. The home is a place of organization and quiet industry.', 'You maintain a tidy, highly organized home. Your childhood may have involved a focus on chores, health, or practical duties rather than emotional expression.', 'Creating a healthy, efficient, and well-managed household, dedicating yourself to the practical care of family members, and attention to detail.', 'Over-criticizing family members, an inability to relax at home due to a never-ending list of chores, and anxiety regarding domestic perfection.', 'You show love at home through acts of service. You need a partner who appreciates cleanliness and practical contribution.', 'Learn to relax your standards at home. A home is meant to be lived in, not just cleaned. Cultivate emotional warmth over mere efficiency.'),
('House 4', 'Libra', 'The emotional foundation is built on harmony, aesthetics, and partnership. The home must be a place of peace and beautiful balance.', 'You strive to create a beautiful, harmonious living environment. You detest conflict at home and may have grown up in an environment that prioritized appearances or diplomacy.', 'Excellent taste in home decor, the ability to mediate family disputes, and creating a truly welcoming, peaceful atmosphere.', 'Sweeping domestic problems under the rug to avoid arguments, indecisiveness regarding household matters, and relying on a partner to create the home.', 'You view the home as a shared enterprise and hate living alone. You need a domestic partner who values peace as much as you do.', 'Learn that healthy conflict is sometimes necessary to maintain true domestic harmony. Do not compromise your own needs just to keep the peace.'),
('House 4', 'Scorpio', 'The foundation of the self is intense, transformative, and deeply private. The home is a fortress, and childhood may have involved secrets or profound emotional crises.', 'You are fiercely protective of your private life. Your home is a place of deep psychological renewal, and you only allow highly trusted individuals into your inner sanctum.', 'Incredible emotional resilience, the ability to support family through massive crises, and a deep, unspoken understanding of familial bonds.', 'Paranoia, holding onto childhood resentments, controlling behavior within the family, and a tendency to create unnecessary domestic drama.', 'You demand absolute loyalty and emotional depth from those you live with. Betrayal in the domestic sphere is unforgivable to you.', 'Learn to let go of past familial traumas. Trust that your home can be a place of light and relaxation, not just a bunker for survival.'),
('House 4', 'Sagittarius', 'The foundation of the self is expansive, philosophical, and freedom-loving. The concept of home is broad; the world is your home.', 'You may come from a diverse, religious, or well-traveled family. You dislike feeling tied down to one location and prefer a home that feels spacious and culturally rich.', 'A tolerant and optimistic domestic environment, the ability to make a home anywhere in the world, and inspiring a love of learning in family members.', 'Avoiding domestic responsibilities, a lack of rootedness that can lead to feeling lost, and preaching at family members rather than listening.', 'You need a partner who respects your need for space and adventure, even within the domestic sphere. Clingy family dynamics suffocate you.', 'Learn the value of putting down roots. Freedom is wonderful, but a stable home base can provide the security needed for even greater adventures.'),
('House 4', 'Capricorn', 'The emotional foundation is structured, disciplined, and focused on duty. Childhood may have been strict, demanding, or focused on reputation and achievement.', 'You view the home as a serious responsibility. You take charge of domestic matters and strive to build a solid, respectable family legacy.', 'Providing immense material security for your family, preserving family traditions, and a stoic resilience that anchors the household.', 'Emotional coldness at home, treating family members like employees, and a relentless focus on duty that crushes spontaneous joy.', 'You express care by providing structure and security. You need a partner who is equally responsible and respects traditional domestic roles.', 'Learn to separate your career ambitions from your private life. Allow your home to be a place of emotional vulnerability and relaxation.'),
('House 4', 'Aquarius', 'The foundation of the self is unconventional, progressive, and intellectually detached. The home is a place for friends, ideas, and independence.', 'Your childhood may have been unusual or disruptive. You prefer a living situation that defies tradition, perhaps living communally or maintaining a highly independent household.', 'A tolerant, open-minded family dynamic, welcoming diverse people into your home, and fostering independence in your loved ones.', 'Emotional detachment from family, unpredictability that creates an unstable home life, and rebelling against domestic routines just for the sake of it.', 'You treat family members like friends. You need a partner who allows you a massive amount of personal space within the home.', 'Learn to cultivate deep, emotional roots, not just intellectual ones. Your family needs your heart just as much as your mind.'),
('House 4', 'Pisces', 'The emotional foundation is fluid, spiritual, and deeply empathetic. The home is a sanctuary for dreaming, healing, and escaping the harsh world.', 'You seek a mystical or highly artistic home environment. Your boundaries with family may be blurred, and your childhood may have involved sacrifice or a lack of clear structure.', 'Profound empathy for family members, creating a spiritually uplifting domestic space, and unconditional love for your roots.', 'A lack of domestic boundaries, enabling toxic family behavior, a chaotic or disorganized home life, and a tendency to play the martyr at home.', 'You seek a soulful, almost psychic connection with those you live with. You must be careful not to absorb the negative emotions of your household.', 'Establish clear, firm boundaries with your family. Learn to ground your domestic life in practical reality so your home does not dissolve into chaos.'),
('House 5', 'Aries', 'Creativity, romance, and self-expression are pursued with fiery passion, courage, and a competitive spirit. Joy is found in the thrill of the chase.', 'You dive headfirst into romances and hobbies with boundless enthusiasm. You love sports, active games, and being the bold initiator in love affairs.', 'Fearless self-expression, a vibrant and infectious joy, the ability to infuse projects with massive energy, and a playful, childlike spirit.', 'Losing interest quickly once the thrill is gone, impulsivity in gambling or romance, and a tendency to be aggressive or overly competitive in fun.', 'In romance, you are passionate and direct. You need a lover who can match your energy and keep you on your toes.', 'Learn to sustain your passions past the initial spark. True creative mastery and deep romance require patience and endurance.'),
('House 5', 'Taurus', 'Creativity and pleasure are deeply rooted in the physical senses, beauty, and stability. Joy is found in creating tangible art and enjoying the finer things in life.', 'Your approach to romance is slow, sensual, and steady. You enjoy hobbies that produce something beautiful and lasting, like gardening, pottery, or music.', 'Steadfast dedication to creative projects, an incredible capacity for sensual enjoyment, and unwavering loyalty in romance once committed.', 'Possessiveness in love, a reluctance to try new hobbies, and a tendency to prioritize material pleasure over emotional depth.', 'You are a deeply affectionate and reliable lover. You express romance through physical touch and luxurious gifts, seeking long-term stability.', 'Allow spontaneity into your romantic and creative life. Do not let the need for security stifle your artistic experimentation.'),
('House 5', 'Gemini', 'Creativity and joy are found in intellectual stimulation, communication, and variety. Romance is a game of the mind.', 'You are flirtatious, witty, and need constant mental engagement to stay interested in a lover or a hobby. You likely have many creative projects going on simultaneously.', 'Exceptional verbal creativity, the ability to keep romance fun and lighthearted, and a brilliant, adaptable approach to artistic expression.', 'Fickleness in love, abandoning creative projects halfway through, and intellectualizing emotions rather than truly feeling them in romance.', 'You need a partner who is, first and foremost, a fascinating conversationalist. Boredom is the quickest way to end a romance with you.', 'Learn to focus your creative energy on completing one project at a time. In love, strive for emotional depth beyond just clever banter.'),
('House 5', 'Cancer', 'Creativity and romance are deeply emotional, nurturing, and tied to the soul. Joy is found in protecting and caring for what you create or love.', 'You pour your heart into your creative endeavors and romantic relationships. You may have a strong desire for children or treat your creative projects as your "babies."', 'Profound emotional depth in art, fiercely protective love, and a nurturing approach to romance that makes partners feel incredibly safe.', 'Over-attachment to lovers, getting easily hurt by minor criticisms of your creative work, and a tendency to smother those you care about.', 'You are deeply romantic and seek soul-level merging. You need a lover who appreciates your sensitivity and offers absolute emotional security.', 'Learn to let go of your creations and your lovers when necessary. True love and art require breathing room to flourish independently.'),
('House 5', 'Leo', 'Creativity, romance, and self-expression are dramatic, radiant, and larger than life. Joy is found in being the center of attention and expressing your heart completely.', 'You are a natural performer, whether on a literal stage or in your daily life. You treat romance like a cinematic love story and demand adoration.', 'Immense creative charisma, a huge capacity for joy and playfulness, generosity in love, and the ability to inspire audiences.', 'Excessive need for applause, dramatic ego clashes in romance, vanity, and a tendency to treat lovers as an audience rather than equals.', 'In romance, you are fiercely loyal and expect to be treated like royalty. You shower your lovers with grand gestures and demand the same in return.', 'Learn that your creative worth is intrinsic, not dependent on external validation. In love, remember to shine the spotlight on your partner as well.'),
('House 5', 'Virgo', 'Creativity and pleasure are found in order, technique, and practical perfection. Romance is approached with caution and a desire to serve.', 'You find joy in hobbies that require precision and skill, like writing, coding, or crafts. You are modest in romance and express love through practical helpfulness.', 'Masterful technical skills in art, a dedication to perfecting your craft, and a reliable, attentive approach to romantic partners.', 'Over-analyzing romance, being overly critical of your own creative work (often preventing you from sharing it), and struggling to just relax and have fun.', 'You are picky in love, seeking a partner who meets your high standards. You show affection by fixing problems and managing the details of your lover’s life.', 'Learn to silence your inner critic. Creativity is often messy, and romance requires vulnerability. Allow yourself to enjoy the process without demanding perfection.'),
('House 5', 'Libra', 'Creativity and joy are centered around aesthetics, harmony, and partnership. Romance is the ultimate art form.', 'You have a refined sense of beauty and likely enjoy the arts, fashion, or design. You are highly romantic and feel most creatively inspired when collaborating with others.', 'Exceptional artistic taste, natural charm that attracts romance effortlessly, and a talent for creating beauty and harmony in all endeavors.', 'Becoming overly dependent on a romantic partner for happiness, indecisiveness in creative projects, and compromising your art just to please others.', 'You are a true romantic, seeking a fairy-tale partnership. You view love as an equal exchange and detest vulgarity or conflict in romance.', 'Learn to find your creative muse within yourself, not just in a partner. Cultivate the ability to stand alone and create art that is uniquely yours.'),
('House 5', 'Scorpio', 'Creativity and romance are intense, passionate, and transformative. Joy is found in delving into the deepest mysteries of life and love.', 'You do not do casual romance; you seek soul-consuming passion. Your creative projects are often profound, psychological, or deal with taboo subjects.', 'Magnetic romantic presence, the ability to create incredibly powerful and transformative art, and unwavering loyalty once trust is established.', 'Obsessive jealousy, a need to control romantic partners, a tendency toward destructive dramatic affairs, and hoarding your creative work out of paranoia.', 'You demand absolute intimacy and transparency from a lover. You are fiercely protective but can easily fall into power struggles in romance.', 'Learn to release control in love and art. Trust that vulnerability is not weakness, and allow your intense passions to heal rather than destroy.'),
('House 5', 'Sagittarius', 'Creativity and romance are expansive, adventurous, and philosophical. Joy is found in exploring new horizons, both mentally and physically.', 'You approach romance as a grand adventure, enjoying playful and diverse affairs. You find creative inspiration through travel, philosophy, and learning about different cultures.', 'Boundless enthusiasm for creative projects, a fun and jovial approach to romance, and the ability to inspire others with your visionary ideas.', 'Fear of commitment in romance, abandoning creative projects when they become tedious, and a tendency to gamble recklessly for fun.', 'You need a lover who is also an adventurer and a philosopher. You despise feeling tied down and require immense freedom in your romantic life.', 'Learn the value of creative discipline. While exploration is vital, true mastery requires sticking with a project or a partner through the mundane moments.'),
('House 5', 'Capricorn', 'Creativity and joy are structured, ambitious, and tied to tangible achievements. Romance is approached cautiously and with long-term goals in mind.', 'You find pleasure in building things that last. Your creative projects often have a practical or business application. In romance, you take your time and prefer traditional courtship.', 'Exceptional discipline in mastering creative skills, the ability to turn hobbies into successful businesses, and absolute reliability in romantic commitments.', 'Suppressing your inner child, a fear of taking creative risks, treating romance like a business transaction, and struggling to just let loose and have fun.', 'You seek a partner who is ambitious and respectable. You express love by providing security and structure rather than grand emotional displays.', 'Allow yourself to experience joy just for the sake of joy, not for achievement. Unchain your inner child and let yourself play without an agenda.'),
('House 5', 'Aquarius', 'Creativity and romance are unconventional, progressive, and highly individualistic. Joy is found in breaking the rules and exploring the avant-garde.', 'You are drawn to unique, futuristic, or eccentric hobbies. In romance, you are friendly but detached, preferring unconventional relationship structures.', 'Brilliant originality, the ability to invent entirely new forms of artistic expression, and a tolerant, open-minded approach to love.', 'Emotional detachment that frustrates romantic partners, rebelling against creative norms just to be contrary, and a fear of deep, messy emotional intimacy.', 'You need a lover who is your best friend first and foremost. You demand intellectual freedom and will quickly exit any relationship that feels stifling.', 'Learn to integrate the heart with the mind. True creative genius and fulfilling romance require emotional depth, not just intellectual brilliance.'),
('House 5', 'Pisces', 'Creativity and romance are mystical, deeply empathetic, and boundless. Joy is found in escaping into imagination and spiritual connection.', 'Your creative potential is massive, often channeled through music, film, or poetry. In romance, you are the ultimate dreamer, seeking a transcendent soulmate connection.', 'Profound artistic inspiration drawn from the collective unconscious, supreme romantic devotion, and a magical, enchanting creative presence.', 'Getting lost in illusions, falling for unavailable or toxic partners (the savior/victim complex), and a lack of discipline to actually finish creative projects.', 'You are incredibly romantic and prone to projecting your fantasies onto your lover. You must be careful not to lose your identity in a relationship.', 'Ground your vast imagination in reality. Develop the discipline to manifest your dreams into actual art, and learn to see your romantic partners as they truly are.'),
('House 6', 'Aries', 'Work, daily routines, and health are approached with fierce energy, independence, and a desire to lead. You want to be a pioneer in your daily environment.', 'You work at a rapid pace and prefer tasks that require quick action and initiative. You hate micromanagement and prefer to be your own boss in your daily duties.', 'Incredible stamina, the ability to initiate new projects effortlessly, and a courageous approach to tackling difficult daily problems.', 'Impatience with slow coworkers, a tendency to burn out by pushing yourself too hard physically, and a lack of follow-through on routine tasks.', 'You engage with colleagues dynamically but can be combative if you feel restricted. You need an active, competitive work environment.', 'Pace yourself. Learn that consistency is just as important as speed, and practice patience with those who do not share your rapid energy.'),
('House 6', 'Taurus', 'Work, daily routines, and health are built on stability, patience, and a desire for tangible results. You approach your duties with methodical endurance.', 'You are the bedrock of any workplace. You prefer a steady, predictable routine and have a talent for bringing structure and beauty into your daily tasks.', 'Unwavering reliability, exceptional endurance, the ability to produce high-quality, lasting work, and a practical approach to health.', 'Stubborn resistance to new work methods, a tendency to get stuck in a rut, and potential laziness if you become too comfortable.', 'You are a steadfast colleague. You express care through practical help in the workplace but dislike sudden changes to the agenda.', 'Embrace innovation in your daily routines. Understand that flexibility can improve efficiency, even if it disrupts your comfort zone initially.'),
('House 6', 'Gemini', 'Work, daily routines, and health require mental stimulation, communication, and variety. A static, repetitive job is your worst nightmare.', 'You likely juggle multiple tasks at once and thrive in environments where you can talk, write, or move around constantly. You need intellectual engagement to stay healthy.', 'Exceptional multitasking abilities, brilliant problem-solving skills, and the capacity to adapt quickly to changing daily demands.', 'Nervous exhaustion, scattered energy, leaving tasks unfinished, and a tendency to gossip or become easily distracted at work.', 'You are a communicative and lively coworker. You need a vibrant, talkative workplace to feel engaged.', 'Develop mental discipline. Focus your brilliant mind on completing one task before moving to the next. Practice mindfulness to calm your nervous system.'),
('House 6', 'Cancer', 'Work, daily routines, and health are deeply tied to emotion, nurturing, and a need for a secure environment. You want your workplace to feel like home.', 'You approach your daily duties with care and intuition. You may work in fields related to caregiving, food, or real estate, and you are highly sensitive to the mood of your workplace.', 'Profound dedication to serving others, the ability to nurture coworkers, and a strong intuition for what needs to be done to create harmony.', 'Taking workplace criticisms too personally, moody fluctuations that affect your productivity, and absorbing the stress of your environment.', 'You act as the "work parent," often caring for your colleagues. You need a supportive, emotionally safe work environment to thrive.', 'Establish emotional boundaries at work. Do not take on the emotional baggage of your coworkers, and learn to accept constructive criticism objectively.'),
('House 6', 'Leo', 'Work, daily routines, and health are approached with pride, creativity, and a need for recognition. You want to shine in your daily duties.', 'Even in routine tasks, you try to inject flair and leadership. You take great pride in your work and expect your efforts to be acknowledged and praised.', 'Charismatic leadership in the workplace, the ability to inspire coworkers, and a generous, warm approach to daily service.', 'Arrogance, refusing to do "menial" tasks, dominating colleagues, and suffering health issues due to stress when your ego is bruised.', 'You expect loyalty and admiration from your coworkers. You are generous with your help but must be the recognized leader of the pack.', 'Learn that true service does not always require an audience. Find joy in doing a job well, even if no one is watching.'),
('House 6', 'Virgo', 'Work, daily routines, and health are the absolute core of this placement. You approach duties with analytical brilliance and a relentless drive for perfection.', 'You are the ultimate organizer. You excel at optimizing routines, analyzing data, and finding practical solutions to complex daily problems. You are highly conscious of health and diet.', 'Unmatched analytical skills, meticulous attention to detail, a profound work ethic, and a genuine, humble desire to be of service.', 'Extreme perfectionism, nitpicking coworkers, working yourself to the point of anxiety-induced illness, and never feeling like your work is "good enough."', 'You show you care by fixing things and organizing your colleagues. You demand competence and can be highly critical of lazy coworkers.', 'Learn to silence your inner critic. Accept that "good enough" is often perfect, and allow yourself time to rest without feeling guilty.'),
('House 6', 'Libra', 'Work, daily routines, and health are centered around balance, aesthetics, and partnership. A harmonious work environment is essential for your well-being.', 'You excel in jobs requiring diplomacy, design, or collaboration. You strive to make your workspace beautiful and go out of your way to keep the peace among colleagues.', 'Excellent mediation skills, a talent for creating a pleasant work atmosphere, and the ability to work beautifully in partnerships.', 'Indecisiveness regarding daily tasks, avoiding necessary confrontations at work, and compromising your own health or boundaries to please others.', 'You view coworkers as partners and thrive in collaborative settings. You detest conflict and may struggle in a highly competitive workplace.', 'Do not sacrifice your own needs for the sake of artificial peace. Learn to assert yourself and handle healthy conflict in your daily life.'),
('House 6', 'Scorpio', 'Work, daily routines, and health are approached with intensity, absolute focus, and a desire for transformation. You do not do superficial work.', 'You dive deeply into your tasks, often preferring research, investigation, or crisis management. You are intensely private about your daily routines and have incredible physical resilience.', 'Unwavering focus, the ability to solve the most difficult problems, profound resourcefulness, and the capacity to regenerate your health after a crisis.', 'Obsessive behavior at work, power struggles with colleagues, paranoia, and a tendency to hold onto stress until it physically manifests.', 'You are a formidable coworker who demands absolute dedication. You are fiercely loyal to trusted colleagues but ruthless if betrayed.', 'Learn to let go of the need to control every aspect of your work. Practice relaxation techniques to release the intense psychological pressure you put on yourself.'),
('House 6', 'Sagittarius', 'Work, daily routines, and health are approached with optimism, a need for freedom, and a philosophical mindset. You hate feeling confined by a cubicle.', 'You need a job that offers variety, travel, or the opportunity to teach. You approach daily tasks with enthusiasm but despise being bogged down by minute details.', 'Visionary problem-solving, an infectious enthusiasm that uplifts coworkers, and the ability to see the "big picture" of any project.', 'Overlooking crucial details, avoiding routine responsibilities, restlessness, and promising more than you can practically deliver in a day.', 'You are a jovial and inspiring colleague. You prefer a laid-back work environment and chafe under strict management or rigid schedules.', 'Cultivate discipline regarding the mundane details of life. Big visions require solid, practical execution to become reality.'),
('House 6', 'Capricorn', 'Work, daily routines, and health are approached with supreme discipline, ambition, and a sense of duty. You view daily tasks as stepping stones to greater authority.', 'You are highly organized, serious, and incredibly hardworking. You likely take on a managerial role naturally, ensuring that operations run with maximum efficiency.', 'Exceptional executive skills, unwavering reliability, the ability to handle massive workloads, and a strategic approach to daily problems.', 'Workaholism, a tendency to view colleagues merely as tools for success, pessimism, and neglecting physical health in the pursuit of ambition.', 'You are a demanding but fair coworker or boss. You respect competence and authority, viewing work relationships through a professional, structured lens.', 'Remember that you are a human being, not a machine. Prioritize your physical and mental health, and learn to delegate tasks.'),
('House 6', 'Aquarius', 'Work, daily routines, and health are unconventional, innovative, and focused on progressive ideals. You need to do things your own unique way.', 'You likely use technology or inventive methods to streamline your routines. You chafe under traditional office rules and prefer a flexible, independent work structure.', 'Brilliant originality in problem-solving, a humanitarian approach to service, and the ability to modernize outdated systems.', 'Rebelling against standard procedures just to be contrary, emotional detachment from colleagues, and unpredictable work habits.', 'You view your coworkers as a community of equals. You are friendly but demand intellectual freedom and personal space in the workplace.', 'Learn to integrate your brilliant ideas within existing structures. Sometimes, standard procedures exist for a reason; learn to innovate without causing chaos.'),
('House 6', 'Pisces', 'Work, daily routines, and health are fluid, intuitive, and deeply compassionate. You serve others with profound empathy but may struggle with practical boundaries.', 'You work best in a creative, healing, or spiritual environment. You lack a rigid routine, preferring to go with the flow, and you easily absorb the stress of your workplace.', 'Boundless compassion for coworkers, immense creative inspiration in daily tasks, and the ability to heal or comfort those you serve.', 'A lack of organization, chronic daydreaming, falling victim to manipulative colleagues, and neglecting your own health to serve others.', 'You are an incredibly sympathetic coworker. You must be careful not to take on everyone else''s problems, as you can easily become emotionally drained.', 'Establish strong boundaries in your daily life. Ground your immense compassion with practical organization and prioritize your own health.')
;`

	valuesStr := strings.TrimPrefix(rawData, "INSERT INTO houses_data (house_name, zodiac_sign, core_meaning, in_real_life, strengths, challenges, relationships, path_of_growth) VALUES\n")
	valuesStr = strings.TrimSpace(valuesStr)
	valuesStr = strings.TrimSuffix(valuesStr, ";")

	ctx := context.Background()
	conn, err := pgx.Connect(ctx, "postgres://zodiac_user:zodiac_pass@localhost:5432/zodiac_db?sslmode=disable")
	if err != nil {
		log.Fatalf("Unable to connect to database: %v\n", err)
	}
	defer conn.Close(ctx)

	insertQuery := fmt.Sprintf(`
		WITH data(house_name, zodiac_sign, core_meaning, real_life, strengths, challenges, relationships, growth_path) AS (
			VALUES %s
		)
		INSERT INTO placement_interpretations (
			language, factor_type, factor_value_1, factor_value_3, factor_value_2,
			core_meaning, real_life, strengths, challenges, relationships, growth_path
		)
		SELECT 
			'en', 
			'house_in_sign', 
			trim(replace(house_name, 'House', '')), 
			'', 
			zodiac_sign,
			core_meaning, real_life, strengths, challenges, relationships, growth_path
		FROM data
		ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3)
		DO UPDATE SET
			core_meaning = EXCLUDED.core_meaning,
			real_life = EXCLUDED.real_life,
			strengths = EXCLUDED.strengths,
			challenges = EXCLUDED.challenges,
			relationships = EXCLUDED.relationships,
			growth_path = EXCLUDED.growth_path,
			updated_at = CURRENT_TIMESTAMP;
	`, valuesStr)

	tag, err := conn.Exec(ctx, insertQuery)
	if err != nil {
		log.Fatalf("Insert failed: %v", err)
	}

	fmt.Printf("Successfully inserted/updated House 4-6 data! Rows affected: %d\n", tag.RowsAffected())
}
